<template>
<section class="dm-view stock-swarm-messages" aria-label="Stock agent messages"><header><div><span class="message-mark"><ResearchIcon name="network"/></span><h3>Agent messages</h3><small>{{ replaying?'Saved replay':running?'Recorded updates':'Saved discussion' }}</small></div><button @click="$emit('toggle-follow')">{{ paused?(replaying?'Resume replay':running?'Follow updates':'Follow messages'):(replaying?'Pause replay':'Pause following') }}</button></header>
<div class="dm-filter"><select :value="focus" aria-label="Message participant" @change="$emit('select',$event.target.value)"><option value="">All conversations</option><option v-for="person in people" :key="person.id" :value="person.id">{{ person.label }}{{ person.planned?' · queued':'' }}</option></select><span>{{ filtered.length }} messages</span></div>
<div ref="scrollEl" class="dm-scroll" role="log" :aria-live="running&&!paused?'polite':'off'" @wheel="$emit('hold')" @pointerdown="$emit('hold')"><TransitionGroup name="stock-bubble" tag="ol"><li v-for="event in filtered" :key="event.id" :class="{reply:event.kind.includes('response')||event.kind.includes('reply'),detail:Boolean(event.sourceEventId),spotlight:selectedEventId===event.id}"><span class="avatar">{{ initials(name(event.author)) }}</span><div class="message-content"><div class="message-meta"><button class="message-link" @click="$emit('message',event)">{{ name(event.author) }}<span v-if="event.recipients.length"> → {{ event.recipients.map(name).join(', ') }}</span></button><time v-if="event.at" :datetime="new Date(event.at).toISOString()" :title="new Date(event.at).toLocaleString()">{{ event.reused?'Earlier · ':'' }}{{ new Date(event.at).toLocaleTimeString(undefined,{hour:'2-digit',minute:'2-digit'}) }}</time></div><p class="recipient">{{ event.kind.replaceAll('_',' ') }}</p><div class="chat-bubble"><p v-if="event.oneYearView" class="one-year-view">One-year scenario view: {{ event.oneYearView.recommendation?event.oneYearView.recommendation+' · ':'' }}{{ money(event.oneYearView.targetPrice,event.oneYearView.currency) }} · {{ change(event.oneYearView.priceReturn) }} · conditional</p><p>{{ excerpt(event.text,420) }}</p><p v-if="event.rationale" class="message-reason"><b>Reasoning</b> {{ excerpt(event.rationale,260) }}</p><details v-if="event.text.length>420||event.rationale||event.evidenceIds?.length" @toggle="$emit('hold')"><summary>Read original analysis</summary><p>{{ event.text }}</p><p v-if="event.rationale&&event.rationale!==event.text">{{ event.rationale }}</p><small v-if="event.evidenceIds?.length">{{ event.evidenceIds.map(id=>sources.find(s=>s.id===id)?.title||id).join(' · ') }}</small></details></div></div></li></TransitionGroup><div v-if="!filtered.length" class="dm-empty">{{ focus&&people.find(p=>p.id===focus)?.planned?'This investor is queued for the next stage.':replaying?'Replay is starting.':'Messages appear as the team saves its research.' }}</div></div>
<footer><span>{{ paused?'Following paused':replaying?'Original saved messages':'Research, source details and investor reasoning' }}</span><button @click="$emit('discussion',focusLens)">Full discussion<ResearchIcon name="arrow"/></button></footer></section>
</template>
<script setup>
import {computed,nextTick,ref,watch} from 'vue'
import ResearchIcon from './ResearchIcon.vue'
const props=defineProps({events:{type:Array,default:()=>[]},people:{type:Array,default:()=>[]},sources:{type:Array,default:()=>[]},focus:String,paused:Boolean,replaying:Boolean,running:Boolean,selectedEventId:String})
defineEmits(['select','message','hold','toggle-follow','discussion'])
const scrollEl=ref(null)
const filtered=computed(()=>props.events.filter(e=>!props.focus||e.author===props.focus||e.recipients.includes(props.focus)).slice(-180))
const name=id=>props.people.find(p=>p.id===id)?.label||id
const initials=value=>value.split(/\s+/).slice(0,2).map(x=>x[0]).join('').toUpperCase()
const excerpt=(text,limit)=>text.length>limit?text.slice(0,limit-3).replace(/\s+\S*$/,'')+'…':text
const money=(value,currency)=>{try{return new Intl.NumberFormat(undefined,{style:'currency',currency,maximumFractionDigits:2}).format(value)}catch{return value.toFixed(2)+' '+currency}}
const change=value=>(value>0?'+':'')+(value*100).toFixed(1)+'%'
const focusLens=computed(()=>props.people.find(p=>p.id===props.focus)?.lens||'specialists')
watch(()=>[props.events.length,props.focus,props.paused],async()=>{await nextTick();if(!props.paused&&scrollEl.value)scrollEl.value.scrollTop=scrollEl.value.scrollHeight},{immediate:true})
</script>
<style scoped>
.stock-swarm-messages{border:1px solid var(--research-line);border-radius:8px;background:white;overflow:hidden;min-width:0}.stock-swarm-messages>header{display:flex;align-items:center;justify-content:space-between;gap:12px;padding:12px 14px;border-bottom:1px solid var(--research-line)}header>div{display:flex;align-items:center;gap:7px;flex-wrap:wrap}.message-mark{display:grid;place-items:center;width:25px;height:25px;border-radius:6px;background:#ef762410;color:#d97839}.message-mark svg{width:15px;height:15px}h3{font-size:14px;font-weight:550;margin:0}header small{font-size:10px;color:var(--research-muted)}button{border:0;background:none;color:#b9642b;font-family:inherit;font-size:11px;line-height:1.5;cursor:pointer;padding:0}.dm-filter{display:flex;align-items:center;justify-content:space-between;gap:12px;padding:8px 13px;background:#fcfcfd}.dm-filter select{font:11px 'Helvetica Neue',Arial,sans-serif;color:#61748b;max-width:83%;min-height:32px;padding:6px 9px;border:1px solid var(--research-line);border-radius:5px;background:white}.dm-filter>span{font-size:10px;white-space:nowrap;color:var(--research-muted)}.dm-scroll{max-height:285px;min-height:180px;overflow:auto;padding:7px 13px 14px;scrollbar-width:thin;scrollbar-color:#cbd7e4 transparent;overscroll-behavior:contain}.dm-scroll ol{list-style:none;padding:0;margin:0}.dm-scroll li{display:flex;gap:9px;margin:11px 0;align-items:start;min-width:0}.avatar{width:27px;height:27px;flex:none;border-radius:50%;background:#fff2e9;color:#b46d42;font-size:9px;display:grid;place-items:center;border:1px solid #efddcf}.message-content{min-width:0;flex:1}.message-meta{display:flex;gap:8px;align-items:center;flex-wrap:wrap}.message-link{font-size:11px;font-weight:550;text-align:left;color:#40576e;line-height:1.5}.message-link>span{font-weight:400;color:#7e91a5}.message-meta time{font-size:10px;color:var(--research-muted)}.recipient{font-size:9px;color:#8b9bb0;margin:3px 0 6px}.chat-bubble{font-size:12px;line-height:1.7;padding:10px 12px;border:1px solid #f0e4d9;border-radius:0 6px 6px 6px;background:#fff8f2;color:#536982;overflow-wrap:anywhere;white-space:pre-wrap}.chat-bubble p{margin:0}.message-reason{font-size:11px;line-height:1.7;margin-top:8px!important;padding-top:7px;border-top:1px solid #eedccf;color:#76869a}.message-reason b{display:block;font-weight:500;color:#ab693b;font-size:10px;margin-bottom:3px}.reply .chat-bubble{background:#f7fafd;border-color:#e1e9f1}.reply .avatar{background:#eef5fb;color:#6285a6;border-color:#dbe7f3}.detail .chat-bubble{background:#faf9f6;border-color:#ece8e0}.detail .recipient{color:#9d815b}.chat-bubble details{font-size:11px;white-space:normal;margin-top:7px}.chat-bubble summary{cursor:pointer;color:#ac693a}.chat-bubble details p{margin:8px 0;white-space:pre-wrap}.chat-bubble details small{font-size:10px;color:#8494a7}.spotlight .chat-bubble{border-color:#dc9b6c;box-shadow:0 0 0 1px #e976251c}.dm-empty{font-size:12px;line-height:1.7;color:var(--research-muted);padding:22px 6px}.stock-swarm-messages footer{display:flex;justify-content:space-between;gap:12px;padding:9px 13px;border-top:1px solid var(--research-line);font-size:10px;color:var(--research-muted);background:#fcfdfe}.stock-swarm-messages footer button{display:flex;align-items:center;gap:5px}.stock-swarm-messages footer svg{width:13px;height:13px}.stock-bubble-enter-active{transition:opacity .16s,transform .16s}.stock-bubble-enter-from{opacity:0;transform:translateY(7px)}.stock-dark .stock-swarm-messages{background:#111923}.stock-dark .dm-filter,.stock-dark .stock-swarm-messages footer{background:#101923}.stock-dark .dm-filter select{background:#172536;color:#c6d4e4;border-color:#304456}.stock-dark .chat-bubble{background:#182536;color:#c0cedf;border-color:#304255}.stock-dark .reply .chat-bubble{background:#152637;border-color:#2c445e}.stock-dark .detail .chat-bubble{background:#20252e;border-color:#3e3d3b}.stock-dark .message-link{color:#d3deea}.stock-dark .message-link>span{color:#91a9c1}.stock-dark .message-reason{border-color:#35485d;color:#a4b6c9}.stock-dark .message-reason b{color:#dc9c6b}.stock-dark .chat-bubble summary{color:#e29b67}.stock-dark button{color:#e6a674}@media(max-width:700px){.dm-scroll{max-height:320px}.dm-filter select{max-width:82%}.stock-swarm-messages footer{font-size:9px}.message-meta time{font-size:9px}}@media(prefers-reduced-motion:reduce){.stock-bubble-enter-active{transition:none}}
</style>
<style scoped>
.chat-bubble .one-year-view{font-size:11px;font-weight:500;color:#ad693a;margin-bottom:7px}.stock-dark .chat-bubble .one-year-view{color:#e6a674}
</style>
